```js
function update(dt) {
  if (state.mode !== 'playing' && state.mode !== 'ready') return;
  // paddle keyboard
  let dir = 0;
  if (keys['ArrowLeft'] || keys['a'] || keys['A']) dir -= 1;
  if (keys['ArrowRight'] || keys['d'] || keys['D']) dir += 1;
  if (dir) paddle.x = clamp(paddle.x + dir * paddle.speed * dt, 8, W - paddle.w - 8);
  // note: mouse sets paddle.x directly on move

  growTimer = Math.max(0, growTimer - dt);
  if (growTimer === 0 && paddle.w !== paddle.baseW) paddle.w = paddle.baseW;
  slowTimer = Math.max(0, slowTimer - dt);

  if (state.mode === 'ready') {
    for (const b of balls) if (b.stuck) { b.x = paddle.x + paddle.w/2; b.y = paddle.y - b.r - 1; }
    return;
  }

  const slowMul = slowTimer > 0 ? 0.62 : 1;
  for (const b of balls) {
    if (b.stuck) continue;
    const effSpeed = Math.hypot(b.vx, b.vy) * slowMul;
    const steps = Math.max(1, Math.ceil(effSpeed * dt / 6));
    const sdt = dt / steps;
    for (let s = 0; s < steps; s++) {
      b.x += b.vx * sdt * slowMul;
      b.y += b.vy * sdt * slowMul;
      // walls
      if (b.x - b.r < 8) { b.x = 8 + b.r; b.vx = Math.abs(b.vx); beep(220, .04, 'square', .025); }
      if (b.x + b.r > W - 8) { b.x = W - 8 - b.r; b.vx = -Math.abs(b.vx); beep(220, .04, 'square', .025); }
      if (b.y - b.r < 30) { b.y = 30 + b.r; b.vy = Math.abs(b.vy); beep(220, .04, 'square', .025); }
      // paddle
      if (b.vy > 0 && b.y + b.r >= paddle.y && b.y + b.r <= paddle.y + paddle.h + 12 && b.x >= paddle.x - b.r && b.x <= paddle.x + paddle.w + b.r) {
        const rel = clamp((b.x - (paddle.x + paddle.w/2)) / (paddle.w/2), -1, 1);
        const ang = rel * (60 * Math.PI / 180);
        const sp = Math.hypot(b.vx, b.vy);
        b.vx = Math.sin(ang) * sp;
        b.vy = -Math.cos(ang) * sp;
        b.y = paddle.y - b.r - 0.5;
        beep(330, .05, 'square', .03);
      }
      // bricks
      for (const br of bricks) {
        if (br.hp <= 0) continue;
        const cx = clamp(b.x, br.x, br.x + BW);
        const cy = clamp(b.y, br.y, br.y + BH);
        const dx = b.x - cx, dy = b.y - cy;
        if (dx*dx + dy*dy <= b.r*b.r) {
          br.hp--;
          state.score += 5;
          b.speed = Math.min(b.speed + 4, 540);
          // renormalize velocity to speed
          const sp = Math.hypot(b.vx, b.vy) || 1;
          b.vx = b.vx / sp * b.speed; b.vy = b.vy / sp * b.speed;
          if (Math.abs(dx) > Math.abs(dy)) {
            b.vx = Math.abs(b.vx) * (dx >= 0 ? 1 : -1);
            b.x += (dx >= 0 ? 1 : -1) * (b.r - Math.abs(dx) + 1);
          } else {
            b.vy = Math.abs(b.vy) * (dy >= 0 ? 1 : -1);
            b.y += (dy >= 0 ? 1 : -1) * (b.r - Math.abs(dy) + 1);
          }
          if (br.hp <= 0) {
            state.score += 10 * state.level;
            burst(br.x + BW/2, br.y + BH/2, br.color);
            beep(520 + br.row * 40, .06, 'square', .035);
            maybeDrop(br);
          } else {
            beep(300, .05, 'square', .03);
          }
          break;
        }
      }
    }
  }
  // remove fallen balls
  balls = balls.filter(b => b.y - b.r < H + 20);
  if (balls.length === 0) { loseLife(); return; }

  // drops
  for (const d of drops) {
    d.y += d.vy * dt;
    if (d.y + 10 >= paddle.y && d.y <= paddle.y + paddle.h + 6 && d.x >= paddle.x - 10 && d.x <= paddle.x + paddle.w + 10) {
      applyDrop(d.type); d.dead = true;
    }
  }
  drops = drops.filter(d => !d.dead && d.y < H + 20);

  // particles
  for (const p of particles) { p.life -= dt; p.x += p.vx*dt; p.y += p.vy*dt; p.vy += 320*dt; }
  particles = particles.filter(p => p.life > 0);

  // level clear
  if (bricks.every(br => br.hp <= 0)) {
    state.score += 100 * state.level;
    state.mode = 'clear';
    beep(523,.1); setTimeout(()=>beep(659,.1),110); setTimeout(()=>beep(784,.15),220);
  }
}
