          }
          if (br.hp <= 0) {
            state.score += 10 * state.level;
            burst(br.x + BW / 2, br.y + BH / 2, br.color);
            beep(520 + br.row * 40, 0.06, 'square', 0.035);
            maybeDrop(br);
          } else {
            beep(300, 0.05, 'square', 0.03);
          }
          break;
        }
      }
    }
  }

  // 落ちたボール除去
  balls = balls.filter(b => b.y - b.r < H + 20);
  if (balls.length === 0) { loseLife(); return; }

  // ドロップ
  for (const d of drops) {
    d.y += d.vy * dt;
    if (d.y + 10 >= paddle.y && d.y <= paddle.y + paddle.h + 6 &&
        d.x >= paddle.x - 10 && d.x <= paddle.x + paddle.w + 10) {
      applyDrop(d.type);
      d.dead = true;
    }
  }
  drops = drops.filter(d => !d.dead && d.y < H + 20);

  // パーティクル
  for (const p of particles) { p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 320 * dt; }
  particles = particles.filter(p => p.life > 0);

  // ステージクリア
  if (bricks.every(br => br.hp <= 0)) {
    state.score += 100 * state.level;
    state.mode = 'clear';
    beep(523, 0.1); setTimeout(() => beep(659, 0.1), 110); setTimeout(() => beep(784, 0.16), 220);
  }
}

// ---------- 描画 ----------
function draw() {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#101828'); g.addColorStop(1, '#1c2333');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // 遊び場の枠（下は開放）
  ctx.strokeStyle = 'rgba(255,255,255,.12)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(8, H); ctx.lineTo(8, 30); ctx.lineTo(W - 8, 30); ctx.lineTo(W - 8, H);
  ctx.stroke();

  // ブロック
  for (const br of bricks) {
    if (br.hp <= 0) continue;
    const f = br.hp === 1 ? 1 : br.hp === 2 ? 0.72 : 0.5;
    ctx.fillStyle = shade(br.color, f);
    roundRect(br.x, br.y, BW, BH, 4); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.18)';
    roundRect(br.x + 2, br.y + 2, BW - 4, BH / 2 - 2, 3); ctx.fill();
    if (br.hp >= 2) {
      ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = 1.5;
      roundRect(br.x + 1, br.y + 1, BW - 2, BH - 2, 3); ctx.stroke();
    }
    if (br.hp === 3) {
      ctx.strokeStyle = 'rgba(255,255,255,.25)'; ctx.lineWidth = 1;
      roundRect(br.x + 4, br.y + 4, BW - 8, BH - 8, 2); ctx.stroke();
    }
  }

  // ドロップ
  for (const d of drops) {
    const info = DROP_INFO[d.type];
    ctx.fillStyle = info.c;
    roundRect(d.x - 11, d.y - 11, 22, 22, 6); ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 14px "Segoe UI", system-ui, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(info.t, d.x, d.y + 1);
  }

  // パドル
  const pg = ctx.createLinearGradient(0, paddle.y, 0, paddle.y + paddle.h);
  pg.addColorStop(0, '#90caf9'); pg.addColorStop(1, '#42a5f5');
  ctx.fillStyle = pg;
  roundRect(paddle.x, paddle.y, paddle.w, paddle.h, 7); ctx.fill();

  // ボール
  for (const b of balls) {
    ctx.save();
    ctx.shadowColor = 'rgba(255,255,255,.7)'; ctx.shadowBlur = 12;
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }

  // パーティクル
  for (const p of particles) {
    ctx.globalAlpha = Math.max(0, p.life / 0.5);
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - 2, p.y - 2, 4, 4);
  }
  ctx.globalAlpha = 1;

  // HUD
  ctx.fillStyle = '#e8eaf0';
  ctx.font = '16px "Segoe UI", system-ui, sans-serif';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';   ctx.fillText(`スコア ${state.score}`, 16, 15);
  ctx.textAlign = 'center'; ctx.fillText(`ベスト ${state.best}`, W / 2, 15);
  ctx.textAlign = 'right';  ctx.fillText(`レベル ${state.level}`, W - 96, 15);
  for (let i = 0; i < state.lives; i++) {
    ctx.beginPath(); ctx.arc(W - 22 - i * 18, 15, 6, 0, Math.PI * 2);
    ctx.fillStyle = '#ffd54f'; ctx.fill();
  }

  // 発射待ちヒント
  if (state.mode === 'ready') {
    ctx.fillStyle = 'rgba(255,255,255,.65)';
    ctx.font = '15px "Segoe UI", system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('スペース / クリックで発射', W / 2, H - 70);
  }

  // オーバーレイ
  if (state.mode === 'title') {
    overlay([
      { text: 'ブロック崩し', big: true },
      { text: 'クリックまたはスペースキーでスタート' },
      { text: 'マウス / ←→キー / タッチ でパドル操作　Pでポーズ' },
    ]);
  } else if (state.mode === 'paused') {
    overlay([{ text: 'ポーズ中', big: true }, { text: 'P で再開' }]);
  } else if (state.mode === 'clear') {
    overlay([
      { text: `ステージ ${state.level} クリア！`, big: true },
      { text: `スコア ${state.score}` },
      { text: 'クリック / スペースで次のステージへ' },
    ]);
  } else if (state.mode === 'over') {
    overlay([
      { text: 'ゲームオーバー', big: true },
      { text: `スコア ${state.score}　ベスト ${state.best}` },
      { text: 'クリック / スペースでリトライ' },
    ]);
  }
}

function overlay(lines) {
  ctx.fillStyle = 'rgba(8,12,20,.74)';
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  let y = H / 2 - (lines.length - 1) * 26;
  for (const ln of lines) {
    ctx.font = ln.big ? 'bold 44px "Segoe UI", system-ui, sans-serif'
                      : '18px "Segoe UI", system-ui, sans-serif';
    ctx.fillStyle = ln.big ? '#ffffff' : '#cfd8e3';
    ctx.fillText(ln.text, W / 2, y);
    y += ln.big ? 64 : 36;
  }
}

// ---------- 入力 ----------
function action() {
  if (state.mode === 'title') startGame();
  else if (state.mode === 'ready') {
    balls.forEach(b => { if (b.stuck) launchBall(b); });
    state.mode = 'playing';
    beep(440, 0.05);
  } else if (state.mode === 'clear') nextLevel();
  else if (state.mode === 'over') startGame();
}
function togglePause() {
  if (state.mode === 'playing' || state.mode === 'ready') {
    state.prevMode = state.mode;
    state.mode = 'paused';
  } else if (state.mode === 'paused') {
    state.mode = state.prevMode || 'playing';
  }
}

window.addEventListener('keydown', e => {
  if ([' ', 'ArrowLeft', 'ArrowRight'].includes(e.key)) e.preventDefault();
  keys[e.key] = true;
  if (e.key === ' ') action();
  if (e.key === 'p' || e.key === 'P' || e.key === 'Escape') togglePause();
});
window.addEventListener('keyup', e => { keys[e.key] = false; });

function pointerX(e) {
  const rect = canvas.getBoundingClientRect();
  const cx = e.touches ? e.touches[0].clientX : e.clientX;
  return (cx - rect.left) * (W / rect.width);
}
function movePaddleTo(x) {
  paddle.x = clamp(x - paddle.w / 2, 8, W - paddle.w - 8);
}
canvas.addEventListener('mousemove', e => movePaddleTo(pointerX(e)));
canvas.addEventListener('touchmove', e => { e.preventDefault(); movePaddleTo(pointerX(e)); }, { passive: false });
canvas.addEventListener('touchstart', e => { movePaddleTo(pointerX(e)); action(); }, { passive: true });
canvas.addEventListener('click', () => action());
window.addEventListener('blur', () => { if (state.mode === 'playing') togglePause(); });

// ---------- メインループ ----------
let last = performance.now();
function frame(now) {
  const dt = Math.min((now - last) / 1000, 1 / 30);
  last = now;
  update(dt);
  draw();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
})();
</script>
</body>
